Premier jalon, **sans fonction**, tout dans `main` :
1. déclare `int t[100], n, v;` ;
2. lis `n` ;
3. lis les `n` valeurs dans `t` (une boucle) ;
4. lis `v` ;
5. déclare `int *r = NULL;` ;
6. parcours le tableau : à la première case égale à `v`, fais `r = &t[i];` puis `break;` ;
7. après la boucle, si `r != NULL` : `*r = 0;` puis affiche le tableau (valeurs séparées par une espace) ; sinon affiche `absent`.

verif.exemple:
#include <stdio.h>

int main(void) {
    int t[100], n, v;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) scanf("%d", &t[i]);
    scanf("%d", &v);
    int *r = NULL;
    for (int i = 0; i < n; i++) {
        if (t[i] == v) {
            r = &t[i];
            break;
        }
    }
    if (r != NULL) {
        *r = 0;
        for (int i = 0; i < n; i++) printf("%d ", t[i]);
        printf("\n");
    } else {
        printf("absent\n");
    }
    return 0;
}

